package com.example.myfschool.service;

import com.example.myfschool.dto.AdminOperationsDtos.*;
import com.example.myfschool.entity.*;
import com.example.myfschool.enums.*;
import com.example.myfschool.exception.*;
import jakarta.persistence.*;
import java.time.*;
import java.util.*;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
@Transactional(readOnly=true)
public class SchoolAdminOperationsService {
    private final EntityManager em;
    private final SchoolAdminAccountService accounts;
    private void invalid(){throw new BusinessException(ErrorCode.INVALID_REQUEST);}
    private void conflict(){throw new BusinessException(ErrorCode.RESOURCE_CONFLICT);}
    private Map<String,Object> map(Object... args){Map<String,Object> m=new LinkedHashMap<>();for(int i=0;i<args.length;i+=2)m.put((String)args[i],args[i+1]);return m;}
    private User writer(Long uid){User a=accounts.admin(uid);em.lock(a.getSchool(),LockModeType.PESSIMISTIC_WRITE);return a;}
    private <T> T scoped(User a,Class<T> type,Long id){
        if(id==null)invalid();T x=em.find(type,id);if(x==null)throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);
        Long school;
        if(x instanceof SchoolClass c)school=c.getSchool().getId();else if(x instanceof User u)school=u.getSchool().getId();
        else if(x instanceof Teacher t)school=t.getSchool().getId();else if(x instanceof AcademicYear y)school=y.getSchool().getId();
        else if(x instanceof Semester s)school=s.getAcademicYear().getSchool().getId();
        else if(x instanceof TeachingAssignment t)school=t.getSchoolClass().getSchool().getId();
        else if(x instanceof TimetableEntry t)school=t.getTeachingAssignment().getSchoolClass().getSchool().getId();
        else if(x instanceof Announcement n)school=n.getSchool().getId();else throw new IllegalArgumentException();
        if(!school.equals(a.getSchool().getId()))throw new BusinessException(ErrorCode.ACCESS_DENIED);return x;
    }
    private void audit(User a,String action,String entity,Long id){AuditLog l=new AuditLog();l.setSchool(a.getSchool());l.setActor(a);l.setAction(action);l.setEntityType(entity);l.setEntityId(id);em.persist(l);}
    private Map<String,Object> slot(TimetableEntry t){TeachingAssignment a=t.getTeachingAssignment();return map("id",t.getId(),"teachingAssignmentId",a.getId(),"classId",a.getSchoolClass().getId(),"teacherId",a.getTeacher().getId(),"subjectId",a.getSubject().getId(),"semesterId",a.getSemester().getId(),"dayOfWeek",t.getDayOfWeek(),"periodNumber",t.getPeriodNumber(),"shift",t.getShift(),"room",t.getRoom(),"effectiveFrom",t.getEffectiveFrom(),"effectiveTo",t.getEffectiveTo());}
    public Map<String,Object> timetable(Long uid,Long classId,Long teacherId,Long semesterId,LocalDate date,int page,int size){
        User a=accounts.admin(uid);SchoolAdminAccountService.page(page,size);if(classId!=null)scoped(a,SchoolClass.class,classId);if(teacherId!=null)scoped(a,Teacher.class,teacherId);if(semesterId!=null)scoped(a,Semester.class,semesterId);
        String w=" where a.schoolClass.school.id=:school"+(classId==null?"":" and a.schoolClass.id=:class")+(teacherId==null?"":" and a.teacher.id=:teacher")+(semesterId==null?"":" and a.semester.id=:semester")+(date==null?"":" and t.effectiveFrom<=:date and (t.effectiveTo is null or t.effectiveTo>=:date)");
        var q=em.createQuery("select t from TimetableEntry t join fetch t.teachingAssignment a join fetch a.schoolClass join fetch a.teacher join fetch a.subject join fetch a.semester"+w+" order by t.dayOfWeek,t.shift,t.periodNumber,t.id",TimetableEntry.class);
        var count=em.createQuery("select count(t) from TimetableEntry t join t.teachingAssignment a"+w,Long.class);
        for(var query:List.of(q,count)){query.setParameter("school",a.getSchool().getId());if(classId!=null)query.setParameter("class",classId);if(teacherId!=null)query.setParameter("teacher",teacherId);if(semesterId!=null)query.setParameter("semester",semesterId);if(date!=null)query.setParameter("date",date);}
        return map("content",q.setFirstResult(page*size).setMaxResults(size).getResultList().stream().map(this::slot).toList(),"page",page,"size",size,"totalElements",count.getSingleResult());
    }
    public Map<String,Object> timetableDetail(Long uid,Long id){return slot(scoped(accounts.admin(uid),TimetableEntry.class,id));}
    public Map<String,Object> assignments(Long uid,Long classId,Long teacherId,Long subjectId,Long semesterId,Long yearId,ActiveStatus status,int page,int size){
        User admin=accounts.admin(uid);SchoolAdminAccountService.page(page,size);
        if(classId!=null)scoped(admin,SchoolClass.class,classId);if(teacherId!=null)scoped(admin,Teacher.class,teacherId);if(semesterId!=null)scoped(admin,Semester.class,semesterId);if(yearId!=null)scoped(admin,AcademicYear.class,yearId);
        if(subjectId!=null){Subject subject=em.find(Subject.class,subjectId);if(subject==null)throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);if(!subject.getSchool().getId().equals(admin.getSchool().getId()))throw new BusinessException(ErrorCode.ACCESS_DENIED);}
        String w=" where a.schoolClass.school.id=:school and a.teacher.school.id=:school and a.subject.school.id=:school and a.semester.academicYear.school.id=:school and a.semester.academicYear.id=a.schoolClass.academicYear.id";
        Map<String,Object> params=new LinkedHashMap<>();params.put("school",admin.getSchool().getId());
        if(classId!=null){w+=" and a.schoolClass.id=:class";params.put("class",classId);}if(teacherId!=null){w+=" and a.teacher.id=:teacher";params.put("teacher",teacherId);}if(subjectId!=null){w+=" and a.subject.id=:subject";params.put("subject",subjectId);}if(semesterId!=null){w+=" and a.semester.id=:semester";params.put("semester",semesterId);}if(yearId!=null){w+=" and a.semester.academicYear.id=:year";params.put("year",yearId);}if(status!=null){w+=" and a.status=:status";params.put("status",status);}
        var q=em.createQuery("select a from TeachingAssignment a join fetch a.schoolClass c join fetch a.teacher t join fetch a.subject s join fetch a.semester sem"+w+" order by c.className,s.name,t.fullName,a.id",TeachingAssignment.class);var count=em.createQuery("select count(a) from TeachingAssignment a"+w,Long.class);params.forEach((k,v)->{q.setParameter(k,v);count.setParameter(k,v);});
        return map("content",q.setFirstResult(page*size).setMaxResults(size).getResultList().stream().map(a->map("id",a.getId(),"classId",a.getSchoolClass().getId(),"className",a.getSchoolClass().getClassName(),"teacherId",a.getTeacher().getId(),"teacherName",a.getTeacher().getFullName(),"subjectId",a.getSubject().getId(),"subjectName",a.getSubject().getName(),"semesterId",a.getSemester().getId(),"academicYearId",a.getSemester().getAcademicYear().getId(),"status",a.getStatus())).toList(),"page",page,"size",size,"totalElements",count.getSingleResult());
    }
    @Transactional public Map<String,Object> timetable(Long uid,Long id,Timetable r){
        User a=writer(uid);TeachingAssignment assignment=scoped(a,TeachingAssignment.class,r.teachingAssignmentId());
        if(!assignment.getTeacher().getSchool().getId().equals(a.getSchool().getId())||!assignment.getSubject().getSchool().getId().equals(a.getSchool().getId())||!assignment.getSemester().getAcademicYear().getSchool().getId().equals(a.getSchool().getId()))throw new BusinessException(ErrorCode.ACCESS_DENIED);
        if(assignment.getStatus()!=ActiveStatus.ACTIVE||assignment.getSchoolClass().getStatus()!=SchoolClassStatus.ACTIVE||assignment.getTeacher().getStatus()!=TeacherStatus.ACTIVE||!assignment.getSubject().isActive())invalid();
        Semester sem=assignment.getSemester();LocalDate end=r.effectiveTo()==null?sem.getEndDate():r.effectiveTo();
        if(!sem.getAcademicYear().getId().equals(assignment.getSchoolClass().getAcademicYear().getId())||r.effectiveFrom().isBefore(sem.getStartDate())||end.isAfter(sem.getEndDate())||end.isBefore(r.effectiveFrom()))invalid();
        TimetableEntry t=id==null?new TimetableEntry():scoped(a,TimetableEntry.class,id);
        String room=r.room()==null||r.room().isBlank()?null:r.room().trim();
        long clashes=em.createQuery("select count(t) from TimetableEntry t join t.teachingAssignment x where x.schoolClass.school.id=:school and (:id is null or t.id<>:id) and x.status=:active and t.dayOfWeek=:day and t.shift=:shift and t.periodNumber=:period and t.effectiveFrom<=:end and (t.effectiveTo is null or t.effectiveTo>=:start) and (x.schoolClass.id=:class or x.teacher.id=:teacher or (:room is not null and t.room=:room))",Long.class)
            .setParameter("school",a.getSchool().getId()).setParameter("id",id).setParameter("active",ActiveStatus.ACTIVE).setParameter("day",r.dayOfWeek()).setParameter("shift",r.shift()).setParameter("period",r.periodNumber()).setParameter("start",r.effectiveFrom()).setParameter("end",end).setParameter("class",assignment.getSchoolClass().getId()).setParameter("teacher",assignment.getTeacher().getId()).setParameter("room",room).getSingleResult();if(clashes>0)conflict();
        t.setTeachingAssignment(assignment);t.setDayOfWeek(r.dayOfWeek());t.setPeriodNumber(r.periodNumber());t.setShift(r.shift());t.setRoom(room);t.setEffectiveFrom(r.effectiveFrom());t.setEffectiveTo(end);if(id==null)em.persist(t);em.flush();audit(a,id==null?"CREATE":"UPDATE","TimetableEntry",t.getId());return slot(t);
    }
    @Transactional public void deleteTimetable(Long uid,Long id){User a=writer(uid);TimetableEntry t=scoped(a,TimetableEntry.class,id);em.remove(t);audit(a,"DELETE","TimetableEntry",id);}
    private Map<String,Object> schoolView(School s){return map("id",s.getId(),"schoolCode",s.getSchoolCode(),"name",s.getName(),"schoolLevel",s.getSchoolLevel(),"address",s.getAddress(),"phone",s.getPhone(),"email",s.getEmail(),"status",s.getStatus());}
    public Map<String,Object> school(Long uid){return schoolView(accounts.admin(uid).getSchool());}
    @Transactional public Map<String,Object> school(Long uid,SchoolInfo r){User a=writer(uid);School s=a.getSchool();s.setName(r.name().trim());s.setSchoolLevel(r.schoolLevel());s.setAddress(r.address());s.setPhone(r.phone());s.setEmail(r.email());audit(a,"UPDATE","School",s.getId());return schoolView(s);}
    private Map<String,Object> noticeView(Announcement n){var targets=em.createQuery("select t from AnnouncementTarget t left join fetch t.schoolClass left join fetch t.user left join fetch t.school where t.announcement.id=:id order by t.id",AnnouncementTarget.class).setParameter("id",n.getId()).getResultList();return map("id",n.getId(),"authorId",n.getAuthor().getId(),"title",n.getTitle(),"content",n.getContent(),"status",n.getStatus(),"publishedAt",n.getPublishedAt(),"expiresAt",n.getExpiresAt(),"targets",targets.stream().map(t->map("type",t.getTargetType(),"id",t.getTargetType()==AnnouncementTargetType.SCHOOL?t.getSchool().getId():t.getTargetType()==AnnouncementTargetType.CLASS?t.getSchoolClass().getId():t.getUser().getId())).toList());}
    @Transactional public Map<String,Object> createNotice(Long uid,Notice r){User a=writer(uid);if(r.expiresAt()!=null&&!r.expiresAt().isAfter(LocalDateTime.now()))invalid();
        Announcement n=new Announcement();n.setSchool(a.getSchool());n.setAuthor(a);n.setTitle(r.title().trim());n.setContent(r.content().trim());n.setExpiresAt(r.expiresAt());n.setStatus(AnnouncementStatus.DRAFT);em.persist(n);Set<String> seen=new HashSet<>();
        for(Target target:r.targets()){AnnouncementTarget t=new AnnouncementTarget();t.setAnnouncement(n);t.setTargetType(target.type());Long targetId=target.id();if(target.type()==AnnouncementTargetType.SCHOOL){if(targetId!=null&&!targetId.equals(a.getSchool().getId()))throw new BusinessException(ErrorCode.ACCESS_DENIED);targetId=a.getSchool().getId();t.setSchool(a.getSchool());}else if(target.type()==AnnouncementTargetType.CLASS)t.setSchoolClass(scoped(a,SchoolClass.class,targetId));else t.setUser(scoped(a,User.class,targetId));if(!seen.add(target.type()+":"+targetId))continue;em.persist(t);}
        em.flush();audit(a,"CREATE","Announcement",n.getId());return noticeView(n);
    }
    @Transactional public Map<String,Object> publish(Long uid,Long id){User a=writer(uid);Announcement n=scoped(a,Announcement.class,id);em.lock(n,LockModeType.PESSIMISTIC_WRITE);if(n.getStatus()==AnnouncementStatus.PUBLISHED)return noticeView(n);if(n.getStatus()!=AnnouncementStatus.DRAFT)conflict();if(n.getExpiresAt()!=null&&!n.getExpiresAt().isAfter(LocalDateTime.now()))conflict();
        var targets=em.createQuery("select t from AnnouncementTarget t where t.announcement.id=:id",AnnouncementTarget.class).setParameter("id",id).getResultList();if(targets.isEmpty())invalid();for(AnnouncementTarget t:targets){if(t.getTargetType()==AnnouncementTargetType.CLASS)scoped(a,SchoolClass.class,t.getSchoolClass().getId());else if(t.getTargetType()==AnnouncementTargetType.USER)scoped(a,User.class,t.getUser().getId());else if(!t.getSchool().getId().equals(a.getSchool().getId()))throw new BusinessException(ErrorCode.ACCESS_DENIED);}
        n.setStatus(AnnouncementStatus.PUBLISHED);n.setPublishedAt(LocalDateTime.now());audit(a,"PUBLISH","Announcement",id);return noticeView(n);}
    @Transactional public Map<String,Object> retract(Long uid,Long id){User a=writer(uid);Announcement n=scoped(a,Announcement.class,id);if(n.getStatus()!=AnnouncementStatus.PUBLISHED)conflict();n.setStatus(AnnouncementStatus.RETRACTED);audit(a,"RETRACT","Announcement",id);return noticeView(n);}
    public Map<String,Object> notice(Long uid,Long id){return noticeView(scoped(accounts.admin(uid),Announcement.class,id));}
    public Map<String,Object> notices(Long uid,AnnouncementStatus status,Long authorId,LocalDate from,LocalDate to,int page,int size){User a=accounts.admin(uid);SchoolAdminAccountService.page(page,size);range(from,to);if(authorId!=null)scoped(a,User.class,authorId);
        String w=" where n.school.id=:s"+(status==null?"":" and n.status=:status")+(authorId==null?"":" and n.author.id=:author")+(from==null?"":" and n.createdAt>=:from")+(to==null?"":" and n.createdAt<:to");var q=em.createQuery("select n from Announcement n join fetch n.author"+w+" order by n.createdAt desc,n.id desc",Announcement.class);var count=em.createQuery("select count(n) from Announcement n"+w,Long.class);for(var x:List.of(q,count)){x.setParameter("s",a.getSchool().getId());if(status!=null)x.setParameter("status",status);if(authorId!=null)x.setParameter("author",authorId);if(from!=null)x.setParameter("from",from.atStartOfDay());if(to!=null)x.setParameter("to",to.plusDays(1).atStartOfDay());}
        return map("content",q.setFirstResult(page*size).setMaxResults(size).getResultList().stream().map(n->map("id",n.getId(),"title",n.getTitle(),"authorId",n.getAuthor().getId(),"status",n.getStatus(),"createdAt",n.getCreatedAt(),"publishedAt",n.getPublishedAt(),"expiresAt",n.getExpiresAt())).toList(),"page",page,"size",size,"totalElements",count.getSingleResult());}
    private void range(LocalDate from,LocalDate to){if(from!=null&&to!=null&&to.isBefore(from))invalid();}
    private List<Map<String,Object>> groups(String jpql,Map<String,Object> params){var q=em.createQuery(jpql,Object[].class);params.forEach(q::setParameter);return q.getResultList().stream().map(r->map("key",r[0],"count",r[1])).toList();}
    public Map<String,Object> students(Long uid,Long yearId){User a=accounts.admin(uid);if(yearId!=null)scoped(a,AcademicYear.class,yearId);String w=" where s.school.id=:s"+(yearId==null?"":" and exists(select e.id from ClassEnrollment e where e.student=s and e.schoolClass.academicYear.id=:year and e.schoolClass.school.id=:s)");Map<String,Object> p=new HashMap<>();p.put("s",a.getSchool().getId());if(yearId!=null)p.put("year",yearId);return map("byStatus",groups("select s.status,count(s) from Student s"+w+" group by s.status",p),"byGender",groups("select s.gender,count(s) from Student s"+w+" group by s.gender",p));}
    public Map<String,Object> teachersClasses(Long uid,Long yearId){User a=accounts.admin(uid);if(yearId!=null)scoped(a,AcademicYear.class,yearId);Map<String,Object> p=new HashMap<>();p.put("s",a.getSchool().getId());if(yearId!=null)p.put("year",yearId);String teacher=" where t.school.id=:s"+(yearId==null?"":" and (exists(select x.id from TeachingAssignment x where x.teacher=t and x.schoolClass.school.id=:s and x.semester.academicYear.id=:year) or exists(select c.id from SchoolClass c where c.homeroomTeacher=t and c.school.id=:s and c.academicYear.id=:year))");String classes=" where c.school.id=:s"+(yearId==null?"":" and c.academicYear.id=:year");return map("teachersByStatus",groups("select t.status,count(t) from Teacher t"+teacher+" group by t.status",p),"classesByStatus",groups("select c.status,count(c) from SchoolClass c"+classes+" group by c.status",p),"classesByGrade",groups("select c.gradeLevel,count(c) from SchoolClass c"+classes+" group by c.gradeLevel",p));}
    public Map<String,Object> attendance(Long uid,Long classId,LocalDate from,LocalDate to){User a=accounts.admin(uid);range(from,to);if(classId!=null)scoped(a,SchoolClass.class,classId);String w=" where s.schoolClass.school.id=:school and s.status<>:cancelled"+(classId==null?"":" and s.schoolClass.id=:class")+(from==null?"":" and s.sessionDate>=:from")+(to==null?"":" and s.sessionDate<=:to");Map<String,Object> p=new HashMap<>();p.put("school",a.getSchool().getId());p.put("cancelled",AttendanceSessionStatus.CANCELLED);if(classId!=null)p.put("class",classId);if(from!=null)p.put("from",from);if(to!=null)p.put("to",to);
        var query=em.createQuery("select count(s) from AttendanceSession s"+w,Long.class);p.forEach(query::setParameter);List<Map<String,Object>> counts=groups("select r.status,count(r) from AttendanceRecord r join r.session s"+w+" and r.student.school.id=:school group by r.status",p);Map<AttendanceStatus,Long> result=new EnumMap<>(AttendanceStatus.class);for(AttendanceStatus s:AttendanceStatus.values())result.put(s,0L);for(var c:counts)result.put((AttendanceStatus)c.get("key"),(Long)c.get("count"));return map("sessionCount",query.getSingleResult(),"recordCount",result.values().stream().mapToLong(Long::longValue).sum(),"counts",result);}
    public Map<String,Object> academics(Long uid,Long classId,Long semesterId){User a=accounts.admin(uid);if(classId!=null)scoped(a,SchoolClass.class,classId);if(semesterId!=null){Semester s=scoped(a,Semester.class,semesterId);if(classId!=null&&!s.getAcademicYear().getId().equals(scoped(a,SchoolClass.class,classId).getAcademicYear().getId()))invalid();}
        String w=" where x.schoolClass.school.id=:school and x.subject.school.id=:school and g.student.school.id=:school"+(classId==null?"":" and x.schoolClass.id=:class")+(semesterId==null?"":" and x.semester.id=:semester");var q=em.createQuery("select x.subject.id,x.subject.name,count(g),count(g.score) from StudentGrade g join g.gradeItem i join i.teachingAssignment x"+w+" group by x.subject.id,x.subject.name order by x.subject.name",Object[].class).setParameter("school",a.getSchool().getId());if(classId!=null)q.setParameter("class",classId);if(semesterId!=null)q.setParameter("semester",semesterId);var grades=q.getResultList().stream().map(r->map("subjectId",r[0],"subjectName",r[1],"gradeRows",r[2],"enteredScores",r[3],"missingScores",(Long)r[2]-(Long)r[3])).toList();
        String ew=" where e.schoolClass.school.id=:school and e.student.school.id=:school"+(classId==null?"":" and e.schoolClass.id=:class")+(semesterId==null?"":" and e.semester.id=:semester");Map<String,Object> p=new HashMap<>();p.put("school",a.getSchool().getId());if(classId!=null)p.put("class",classId);if(semesterId!=null)p.put("semester",semesterId);return map("subjects",grades,"academicResults",groups("select e.academicResult,count(e) from StudentEvaluation e"+ew+" group by e.academicResult",p),"conductResults",groups("select e.conductResult,count(e) from StudentEvaluation e"+ew+" group by e.conductResult",p));}
    public Map<String,Object> auditLogs(Long uid,Long actorId,String action,String entityType,LocalDate from,LocalDate to,int page,int size){User a=accounts.admin(uid);SchoolAdminAccountService.page(page,size);range(from,to);if(actorId!=null)scoped(a,User.class,actorId);if(action!=null&&action.length()>100||entityType!=null&&entityType.length()>100)invalid();String w=" where l.school.id=:school"+(actorId==null?"":" and l.actor.id=:actor")+(action==null?"":" and l.action=:action")+(entityType==null?"":" and l.entityType=:type")+(from==null?"":" and l.createdAt>=:from")+(to==null?"":" and l.createdAt<:to");var q=em.createQuery("select l from AuditLog l left join fetch l.actor"+w+" order by l.createdAt desc,l.id desc",AuditLog.class);var count=em.createQuery("select count(l) from AuditLog l"+w,Long.class);for(var x:List.of(q,count)){x.setParameter("school",a.getSchool().getId());if(actorId!=null)x.setParameter("actor",actorId);if(action!=null)x.setParameter("action",action);if(entityType!=null)x.setParameter("type",entityType);if(from!=null)x.setParameter("from",from.atStartOfDay());if(to!=null)x.setParameter("to",to.plusDays(1).atStartOfDay());}return map("content",q.setFirstResult(page*size).setMaxResults(size).getResultList().stream().map(l->map("id",l.getId(),"actorId",l.getActor()==null?null:l.getActor().getId(),"action",l.getAction(),"entityType",l.getEntityType(),"entityId",l.getEntityId(),"createdAt",l.getCreatedAt())).toList(),"page",page,"size",size,"totalElements",count.getSingleResult());}
}
